const brick=P=>{H.fill(P,'coral',.52);H.hatch(R,P,'blue',4.2,-.9,.55,{tone:.45,amp:.1})};
brick([H.p(-t,-t,h),H.p(w,-t,h),H.p(w,-IN,h),H.p(-t,-IN,h)]);
brick([H.p(-t,-IN,h),H.p(-t,d,h),H.p(-IN,d,h),H.p(-IN,-IN,h)]);
H.fill([H.p(-IN,-IN,h),H.p(w,-IN,h),H.p(w,0,h),H.p(-IN,0,h)],'paper',1);
H.fill([H.p(-IN,0,h),H.p(-IN,d,h),H.p(0,d,h),H.p(0,0,h)],'paper',1);
H.outline(R,[H.p(-t,-t,h),H.p(w,-t,h),H.p(w,0,h),H.p(0,0,h),H.p(0,d,h),H.p(-t,d,h)],'blue',1,{tone:.9,amp:.15});
{const B=H.faceJ(w,-t,t-IN,0,h),Pl=H.faceJ(w,-IN,IN,0,h);
H.fill(B,'coral',.52);H.tint(B,'blue',.30);H.fill(Pl,'paper',1);H.tint(Pl,'blue',.22);
for(let z=.25,k=0;z<h;z+=.25,k++){H.line(R,[H.p(w,-t,z),H.p(w,-IN,z)],'paper',.7,{tone:.8,amp:.03});
const jp=-t+(k%2?.08:.16);H.line(R,[H.p(w,jp,z-.25),H.p(w,jp,z)],'paper',.6,{tone:.7,amp:.03})}
H.outline(R,H.faceJ(w,-t,t,0,h),'blue',1,{tone:.9,amp:.1})}
{const B=H.faceI(-t,d,t-IN,0,h),Pl=H.faceI(-IN,d,IN,0,h);
H.fill(B,'coral',.52);H.tint(B,'blue',.16);H.fill(Pl,'paper',1);H.tint(Pl,'blue',.12);
for(let z=.25,k=0;z<h;z+=.25,k++){H.line(R,[H.p(-t,d,z),H.p(-IN,d,z)],'paper',.7,{tone:.8,amp:.03});
const ip=-t+(k%2?.08:.16);H.line(R,[H.p(ip,d,z-.25),H.p(ip,d,z)],'paper',.6,{tone:.7,amp:.03})}
H.outline(R,H.faceI(-t,d,t,0,h),'blue',1,{tone:.9,amp:.1})}
/* windows */
for(const c of S.win)shellWindow(H,R,c,o.level||1);
/* pilasters: concrete, cut at the top like the plate */
for(const p of S.pil){
boxAt(H,R,p-.17,0,.34,.22,0,h,['paper',1],{shadow:false,topInk:'blue',topTone:.34,half:.07,full:.20,lw:1});
H.grad(H.faceI(p-.17,.22,.34,0,.7),'blue',.14,0,H.p(p,.22,0),H.p(p,.22,.7),4)}
