const DUR={type:.5,'rc-talk':2.4,'rc-reach':1.6,'rc-wave':1.2,talk:2.4,'v-take':1.4,'v-clip':1.6,'v-press':1,wait:5,idle:3,read:4,'bm-look':4};

/* ---- the visitor's route, driven by u so it closes on the beat ---- */
const P_IN=[AT.door,AT.counterFront],P_OUT=[AT.counterFront,AT.bend,AT.liftFront];
function visitorAt(u){const V=LOBBY;
if(u<V.enter||u>=V.gone)return {hidden:true,i:AT.door[0],j:AT.door[1],face:'ne',clip:'walk',phase:0,opacity:0};
if(u<V.counter)return {...walkOn(P_IN,V.enter,V.counter,u),clip:'walk',opacity:sstep(V.enter,V.seen,u)};
if(u<V.leave)return {i:AT.counterFront[0],j:AT.counterFront[1],face:'ne',opacity:1,
  ...seq(u,u,[[V.counter,'talk'],[V.pass-.5,'v-take'],[V.clip,'v-clip'],[V.clipped,'talk']],DUR,.35)};
if(u<V.lift)return {...walkOn(P_OUT,V.leave,V.lift,u),clip:'walk',opacity:1};
if(u<V.opened)return {i:AT.liftFront[0],j:AT.liftFront[1],face:'nw',opacity:1,
  ...seq(u,u,[[V.lift,'wait'],[V.press,'v-press'],[V.open+.1,'wait']],DUR,.25)};
const s=sstep(V.opened,V.gone,u);
return {i:lerp(AT.liftFront[0],AT.liftIn[0],s),j:AT.liftFront[1],face:'nw',clip:'walk',
  phase:s*(AT.liftFront[0]-AT.liftIn[0])/.8,opacity:1-sstep(V.opened+.15,V.gone,u)}}

/* the badge: in the tray, her hand, both hands, then on the coat */
let REC_HAND=null;
function badgeAt(H,R,x,y,a=0){
const B=rotPts(rect(x-3,y-4,x+3,y+4),x,y,a);H.fill(B,'paper',1);
H.fill(rotPts(rect(x-3,y-4,x+3,y-1.6),x,y,a),'teal',.7);
H.outline(R,B,'blue',.7,{amp:.05})}

/* ---- furniture used in more than one place ---- */
function chairAt(H,R,ci,cj,back,o={}){
const s=.30,z=SEATZ,[fx,fy]=H.p(ci,cj,.04);
shadowAt(H,...H.p(ci+.08,cj+.08,0),17,8,.18);
boxAt(H,R,ci-.05,cj-.05,.10,.10,0,z-.08,['blue',.75],{lw:.6,shadow:false});
for(let k=0;k<5;k++){const a=k/5*TAU+(o.turn||0);
H.line(R,[[fx,fy],[fx+Math.cos(a)*13,fy+Math.sin(a)*6.5]],'blue',1.6,{tone:.8,amp:.1})}
boxAt(H,R,ci-s,cj-s,2*s,2*s,z-.08,.08,[o.ink||'teal',o.tone??.55],{lw:.8,shadow:false});
if(back==='nw')boxAt(H,R,ci-s,cj-s,.08,2*s,z,.58,[o.ink||'teal',(o.tone??.55)+.08],{lw:.8,shadow:false});
if(back==='ne')boxAt(H,R,ci-s,cj-s,2*s,.08,z,.58,[o.ink||'teal',(o.tone??.55)+.08],{lw:.8,shadow:false})}

/* the reception counter, as its own baked sprite */
