/* the badge tray, full; a pen pot; a bud vase; the sign-in tablet; sweets */
const T=H.tile(4.70,3.08,.54,.36,zt+.005);H.fill(T,'blue',.55);H.outline(R,T,'blue',.7,{amp:.05});
for(let k=0;k<4;k++){const [x,y]=H.p(4.80+k*.11,3.24,zt+.02);badgeAt(H,R,x,y-2,-.25+k*.14)}
{const [x,y]=H.p(5.45,3.10,zt);const M=rect(x-3,y-8,x+3,y);H.fill(M,'coral',.6);H.outline(R,M,'blue',.7);
for(const [dx,ink] of[[-1.5,'blue'],[.5,'teal'],[2,'coral']])H.line(R,[[x+dx*.7,y-8],[x+dx,y-14]],ink,1,{tone:.85,amp:.05})}
{const [x,y]=H.p(7.05,3.12,zt);bottleAt(H,R,x,y,.6,'teal',.35);
for(const [dx,dy] of[[-3,-15],[2,-17],[0,-19]]){H.line(R,[[x,y-12],[x+dx,y+dy]],'teal',.8,{tone:.8,amp:.1});H.dot(x+dx,y+dy,1.8,'coral',.85,{knock:true})}}
{const P=H.tile(5.62,3.14,.34,.44,zt+.01);H.fill(P,'blue',.80);H.outline(R,P,'blue',.7,{amp:.04});
H.line(R,[lerpP(P[0],P[1],.2),lerpP(P[3],P[2],.2)],'paper',.7,{tone:.35,amp:0})}
{const [x,y]=H.p(4.55,3.40,zt);const B=ell(x,y,6,3);H.fill(B,'paper',1);H.tint(B,'sun',.2);H.outline(R,B,'blue',.7);
for(let k=0;k<5;k++)H.dot(x-3+k*1.5,y-1+(k%2),1.1,pk(R,['coral','teal','sun']),.9,{knock:true})}
