/* the reception mug, and its steam: live, on the counter's key */
function steamOn(H,R,x,y,t,k0=0){for(let k=0;k<3;k++){const ph=fract(t*.29+k*.33+k0),rise=ph*20,wob=Math.sin(ph*5+k)*3.2;
H.line(R,curve([[x+wob*.3,y],[x+wob,y-rise*.5],[x-wob*.7,y-rise]],2),'paper',1.4,{tone:(1-ph)*.7,amp:.4})}}

