{boxAt(H,R,1.30,.24,2.00,.44,0,.52,['coral',.46],{topInk:'blue',topTone:.62,lw:1});
for(const [ii,s] of[[1.55,.62],[2.05,.52],[2.55,.66],[3.05,.50]]){const [x,y]=H.p(ii,.46,.52);plant(H,R,x,y+2,s,{pot:'coral',potTone:.46,n:6})}}
