{const F=frameOn(H,R,'ne',7.40,1.25,.40,.66,{ink:'teal',tone:.40});
const [x,y]=centroid(F);H.fill(circ(x,y-2,5),'coral',.6);H.line(R,[[x-7,y+6],[x+7,y+3]],'blue',.8,{tone:.6,amp:.2});
const [px,py]=H.p(8.40,.48,0);shadowAt(H,px+3,py+1,14,6,.18);plant(H,R,px,py,1.05,{pot:'blue',potTone:.55,n:9})}
