boxAt(H,R,B.i,B.j,B.w,B.d,.36,.08,['sun',.58],{topInk:'sun',topTone:.46,lw:.9,shadow:false});
boxAt(H,R,B.i,B.j,B.w,.10,.44,.44,['sun',.62],{lw:.8,shadow:false});
boxAt(H,R,B.i+.12,B.j+.10,.40,.36,.44,.14,['teal',.52],{lw:.7,shadow:false});
