const lit=1+Math.round(3*sstep(V.up,V.top,u)*(1-sstep(V.down,V.home,u)));
const called=sstep(V.press+.25,V.press+.35,u)*(1-sstep(V.open,V.open+.2,u));
H.at(.02,SHELL.lift.j-.6,0,HH=>{
if(open>.02){const [x,y]=HH.p(.55,SHELL.lift.j,0);HH.glow(x,y,34,14,'sun',.32*open)}
liftDoors(HH,R,open);liftLamp(HH,R,lit);liftCall(HH,R,called)});

/* the counter: one sprite, sorted between the two women. when the visitor
   is in front of it, it slips just behind her. */
