for(const [p,wd] of[[a+.35,.16],[a+.62,.07]]){const Sq=[wallPt(H,'ne',p,z0,g),wallPt(H,'ne',p+wd,z0,g),wallPt(H,'ne',p+wd+.5,z1,g),wallPt(H,'ne',p+.5,z1,g)];
H.opacity(.22,()=>H.knock(Sq))}
