/* motes in the sun. raw t, periods that do not divide any cycle */
function shellDust(H,t,n=5){
const S=SHELL,[ki,kj]=S.sun,DR=streamOf('shell','dust');
H.at(1.2,0,0,HH=>{for(const c of S.win)for(let k=0;k<n;k++){
const p=c+rd(DR,-1.0,1.0),zz=rd(DR,S.winZ,S.winZ+S.winH),sp=rd(DR,.045,.10),ph=fract(t*sp+rd(DR,0,1));
const f=lerp(.15,.85,ph),[x,y]=HH.p(p+f*zz*ki,f*zz*kj+Math.sin(t*.37+k)*.05,zz*(1-f));
HH.dot(x,y,rd(DR,.5,1.1),'sun',(1-Math.abs(ph*2-1))*.75)}})}

/* SPRITES: furniture a figure passes behind, baked once per boil variant and
   scale, then blitted under one H.at key. Static furniture is never redrawn
   in live. Their ink marks still count toward STAGE.audit's total. */
const SPRITES=new Map();
function boxBB(H,i,j,w,d,z0,z1,pad=16){
const P=[];for(const a of[i,i+w])for(const b of[j,j+d])for(const z of[z0,z1])P.push(H.p(a,b,z));
const [x0,y0,x1,y1]=bbox(P);return [x0-pad,y0-pad,x1+pad,y1+pad]}
function sprite(HH,name,bb,draw){
const c=HH.ctx(),m=c.getTransform(),s=Math.hypot(m.a,m.b);
const ratio=[.5,.75,1,1.5,2,2.25,3,4].find(r=>r>=s-1e-3)||4;
const key=name+'|'+HH.variant+'|'+ratio;
let e=SPRITES.get(key);
if(!e){const cv=document.createElement('canvas');
cv.width=Math.max(1,Math.ceil((bb[2]-bb[0])*ratio));cv.height=Math.max(1,Math.ceil((bb[3]-bb[1])*ratio));
const c2=cv.getContext('2d');c2.setTransform(ratio,0,0,ratio,-bb[0]*ratio,-bb[1]*ratio);
const H2=mkHand({ctx:c2,boil:HH.variant}),m0=MARKS;
try{draw(H2,streamOf('sprite',name))}catch(err){console.error('sprite '+name+' '+err.message)}
e={cv,marks:MARKS-m0,w:cv.width/ratio,h:cv.height/ratio};SPRITES.set(key,e)}
c.drawImage(e.cv,bb[0],bb[1],e.w,e.h);MARKS+=e.marks}

/* walk a polyline between two beats at constant speed. phase = distance / 0.8 */
const faceOf=(di,dj)=>Math.abs(di)>=Math.abs(dj)?(di>=0?'se':'nw'):(dj>=0?'sw':'ne');
function walkOn(pts,t0,t1,u){
const L=[0];for(let k=1;k<pts.length;k++)L.push(L[k-1]+Math.hypot(pts[k][0]-pts[k-1][0],pts[k][1]-pts[k-1][1]));
const tot=L[L.length-1],s=clamp((u-t0)/(t1-t0),0,1)*tot;
let k=1;while(k<pts.length-1&&L[k]<s)k++;
const a=pts[k-1],b=pts[k],f=clamp((s-L[k-1])/((L[k]-L[k-1])||1),0,1);
return {i:lerp(a[0],b[0],f),j:lerp(a[1],b[1],f),face:faceOf(b[0]-a[0],b[1]-a[1]),phase:s/.8}}
/* a clip sequence: [[t0,clip],...]; each clip blends into the next over r s */
function seq(u,t,S,DUR,r=.4){
let k=S.length-1;while(k>0&&u<S[k][0])k--;
const cur=S[k][1],nx=k+1<S.length?S[k+1]:null;
const w=nx?sstep(nx[0]-r,nx[0],u):0;
const out={clip:cur,phase:t/(DUR[cur]||3)};
if(w>.001)out.blend={clip:nx[1],phase:t/(DUR[nx[1]]||3),w};
return out}
const SCALE=1.45,SEATZ=FIGURES.seatZ('adult',SCALE);
