const DUR={type:.5,'a-look':3,'a-blow':1.2,'a-cheer':.9,'c-clap':.5,'h-match':.8,'h-set':1,'h-clap':.5,hold:3,idle:3,wait:5};

/* ---- the host's round trip, driven by u ---- */
const H_OUT=[AT.host,AT.hostBend,AT.hostTable],H_BACK=[AT.hostTable,AT.hostBend,AT.host];
function hostAt(u){const T=TEAM;
if(u<T.go)return {i:AT.host[0],j:AT.host[1],face:'ne',...seq(u,u,[[0,'h-set'],[T.strike,'h-match'],[T.shake,'h-set'],[T.pick+.4,'hold']],DUR,.25)};
if(u<T.arrive)return {...walkOn(H_OUT,T.go,T.arrive,u),clip:'carry'};
if(u<T.back)return {i:AT.hostTable[0],j:AT.hostTable[1],face:'ne',
  ...seq(u,u,[[T.arrive,'h-set'],[T.sing,'h-clap'],[T.blow-.2,'hold'],[T.cheer,'h-clap'],[T.take,'h-set'],[T.up+.1,'hold']],DUR,.25)};
if(u<T.home)return {...walkOn(H_BACK,T.back,T.home,u),clip:'carry'};
return {i:AT.host[0],j:AT.host[1],face:'ne',...seq(u,u,[[T.home,'h-set']],DUR,.25)}}
const cakeWhere=u=>u<TEAM.pick+.3||u>=TEAM.rest?'counter':(u>=TEAM.down&&u<TEAM.up)?'table':'hands';
const flameOn=u=>u>=TEAM.lit&&u<TEAM.out;

/* the cake: plate, sponge, icing, one candle. x,y is the plate's centre */
function cakeAt(H,R,x,y,lit,t,smoke){
const P=ell(x,y+1,12,4.8);H.fill(P,'paper',1);H.outline(R,P,'blue',.8,{amp:.05});
const side=[[x-8.5,y-8],[x+8.5,y-8],...arcPts(x,y,8.5,3.4,0,Math.PI,8)];
H.fill(side,'sun',.55);H.tint([[x,y-8],[x+8.5,y-8],...arcPts(x,y,8.5,3.4,0,Math.PI/2,4)],'blue',.18);
H.fill(ell(x,y-8,8.5,3.4),'paper',1);
for(let k=0;k<6;k++){const a=k/6*Math.PI+.25;H.line(R,[[x+Math.cos(a)*8.3,y-8+Math.sin(a)*3.2],[x+Math.cos(a)*8.3,y-5+Math.sin(a)*3+(k%2)*1.5]],'paper',2,{amp:0})}
H.outline(R,[...side],'blue',.9,{amp:.06});H.outline(R,ell(x,y-8,8.5,3.4),'blue',.8,{amp:.05});
for(const [dx,dy] of[[-5,-8.5],[4.5,-7.4],[-.5,-6.6],[2,-9.8]])H.dot(x+dx,y+dy,1.3,'coral',.9,{knock:true});
H.fill(rect(x-1,y-17,x+1,y-8.5),'teal',.7);H.line(R,[[x-1,y-14],[x+1,y-15.5]],'paper',.6,{amp:0});
H.line(R,[[x,y-17],[x,y-18.5]],'blue',.7,{amp:0});
if(lit){const f=.85+.15*Math.sin(t*23.3)+.1*Math.sin(t*9.1),fx=x+Math.sin(t*6.7)*.6;
const F=loop([[fx,y-29*f+1],[fx+3.4,y-21],[fx,y-17.2],[fx-3.4,y-21]],2);
H.glow(fx,y-22,26,19,'sun',.50);H.fill(F,'sun',.95);H.fill(sc(F,fx,y-19.5,.5),'coral',.7)}
if(smoke>0&&smoke<1){const s=smoke,h=10+s*44,dr=Math.sin(s*5)*6;
H.line(R,curve([[x,y-18.5],[x+2+dr*.3,y-18.5-h*.35],[x-3+dr,y-18.5-h*.7],[x+2+dr*1.4,y-18.5-h]],2),'blue',1.5,{tone:.62*(1-s),amp:.5})}}

