{const [x,y]=H.p(8.00,2.78,.775);H.fill(ell(x,y,5,2.2),'paper',1);H.outline(R,ell(x,y,5,2.2),'blue',.6);
for(let k=0;k<3;k++)H.line(R,[[x-3+k*2.5,y-1],[x-3+k*2.5+1,y-10]],['coral','teal','sun'][k],1,{tone:.85,amp:.05})}
